script:
(function () {
  'use strict';
  // Contribution accelerator (auto-escalation). Two plans from the same starting point:
  //   flat:       rate(y) = start
  //   increasing: rate(y) = min(stop, start + step x y), never below start
  // Each year you defer rate x pay (capped at the 402(g) limit plus catch-up for that age when
  // limits apply); the employer matches match% of your deferral up to matchCap% of pay (415(c)
  // cap on deferrals + employer money; pay capped at 401(a)(17)). Deposits go in monthly and
  // compound at (1 + annual return)^(1/12) - 1. Today's dollars = value / (1 + inflation)^years.
  // CHECKS (Node, scratch tests): flat 6% of $50,000 = $3,000 a year = $250/month at 6% for 30
  // years from $0 = 250 x ((1.06^(1/12))^360 - 1) / (1.06^(1/12) - 1) = $243,628.24 (closed
  // form, same as the 401k calculator method); start 3%, +1 point a year, stop 10% -> rates
  // 3,4,...,10,10; start above the stop stays flat; $200,000 at 20% = $40,000 capped at $24,500
  // (age 40), $32,500 (55), $35,750 (61); 50% match up to 6% on 4% deferral = 2% of pay.
  // ---- 2026 IRS 401(k) limits (IRS Notice 2025-67, tax year 2026) ------------------------------
  var LIMITS = {
    year: 2026,
    deferral: 24500,        // 402(g) elective deferral limit (employee pre-tax + Roth)
    catchUp50: 8000,        // catch-up, age 50 or older by year-end
    catchUp60to63: 11250,   // SECURE 2.0 higher catch-up, ages 60-63
    annualAdditions: 72000, // 415(c) limit on deferrals + employer money (catch-up excluded)
    compensation: 360000    // 401(a)(17) maximum pay counted for the plan
  };
  // -----------------------------------------------------------------------------------------------

  function catchUpFor(age) {
    if (age >= 60 && age <= 63) return LIMITS.catchUp60to63;
    if (age >= 50) return LIMITS.catchUp50;
    return 0;
  }

  function rateFor(p, y, increasing) {
    if (!increasing) return p.start;
    return Math.max(p.start, Math.min(p.stop, p.start + p.step * y));
  }

  // One year's employee and employer money at contribution rate `rate`.
  function yearMoney(p, salary, age, rate) {
    var pay = p.limits ? Math.min(salary, LIMITS.compensation) : salary, capped = false;
    var you = pay * rate;
    if (p.limits) {
      var maxYou = LIMITS.deferral + catchUpFor(age);
      if (you > maxYou + 0.005) { you = maxYou; capped = true; }
    }
    var eff = pay > 0 ? you / pay : 0;
    var er = pay * p.match * Math.min(eff, p.matchCap);
    if (p.limits) {
      var regular = Math.min(you, LIMITS.deferral);
      if (regular + er > LIMITS.annualAdditions) { er = Math.max(0, LIMITS.annualAdditions - regular); capped = true; }
    }
    return { you: you, er: er, capped: capped };
  }

  // p: age, retireAge, salary, raise, balance, start, step, stop, match, matchCap, rate,
  // inflation (decimals), limits (bool).
  function project(p) {
    var n = p.retireAge - p.age, i = Math.pow(1 + p.rate, 1 / 12) - 1;
    var salary = p.salary, bF = p.balance, bA = p.balance, rows = [], capped = false, reached = null;
    var t = { youF: 0, youA: 0, erF: 0, erA: 0 };
    for (var y = 0; y < n; y++) {
      var age = p.age + y, rA = rateFor(p, y, true);
      var f = yearMoney(p, salary, age, p.start), a = yearMoney(p, salary, age, rA);
      if (f.capped || a.capped) capped = true;
      if (reached === null && p.stop > p.start && rA >= p.stop - 1e-9) reached = age;
      for (var m = 0; m < 12; m++) {
        bF = bF * (1 + i) + (f.you + f.er) / 12;
        bA = bA * (1 + i) + (a.you + a.er) / 12;
      }
      t.youF += f.you; t.youA += a.you; t.erF += f.er; t.erA += a.er;
      rows.push({ age: age, salary: salary, rate: rA, youF: f.you, youA: a.you, bF: bF, bA: bA });
      salary = salary * (1 + p.raise);
    }
    return { n: n, bF: bF, bA: bA, t: t, rows: rows, capped: capped, reached: reached,
             real: Math.pow(1 + p.inflation, n) };
  }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var money = { format: function (x) { return moneyFmt.format(Math.abs(x) < 0.005 || !isFinite(x) ? 0 : x); } };
  var pctFmt = new Intl.NumberFormat('en-US', { maximumFractionDigits: 2 });

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }

  function update() {
    var age = Math.round(num('caAge')), retireAge = Math.round(num('caRetireAge')), salary = num('caSalary'),
        raise = num('caRaise'), balance = num('caBalance'), start = num('caStart'), step = num('caStep'),
        stop = num('caStop'), match = num('caMatch'), matchCap = num('caMatchCap'), rate = num('caReturn'),
        inflation = num('caInflation'), limits = document.getElementById('caLimits').checked;
    var error = document.getElementById('caError');
    var bad = [age, retireAge, salary, raise, balance, start, step, stop, match, matchCap, rate, inflation].some(isNaN) ||
              age < 16 || age > 99 || retireAge <= age || retireAge > 100 || salary < 0 || balance < 0 || raise < 0 ||
              raise > 20 || start < 0 || start > 100 || step < 0 || step > 10 || stop < 0 || stop > 100 || match < 0 ||
              match > 200 || matchCap < 0 || matchCap > 100 || rate < 0 || rate > 20 || inflation < 0 || inflation > 15;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter an age from 16 to 99 with a retirement age above it (up to 100), non-negative amounts, ' +
                          'contribution rates from 0 to 100%, a yearly step up to 10 points, a match up to 200%, a return up to 20% and inflation up to 15%.';
      return;
    }
    var p = { age: age, retireAge: retireAge, salary: salary, raise: raise / 100, balance: balance, start: start / 100,
              step: step / 100, stop: stop / 100, match: match / 100, matchCap: matchCap / 100, rate: rate / 100,
              inflation: inflation / 100, limits: limits };
    var r = project(p);
    set('caAccelLabel', 'Balance at ' + retireAge + ' with yearly increases');
    set('caFlatLabel', 'Balance at ' + retireAge + ' at a flat ' + pctFmt.format(start) + '%');
    set('caAccel', money.format(r.bA));
    set('caFlat', money.format(r.bF));
    set('caGain', money.format(r.bA - r.bF));
    set('caGainReal', money.format((r.bA - r.bF) / r.real));
    set('caExtraYou', money.format(r.t.youA - r.t.youF));
    set('caExtraMatch', money.format(r.t.erA - r.t.erF));

    if (step <= 0 || stop <= start) {
      set('caSummary', 'With no step or a stop rate at or below your current rate, both plans are the same. Raise the stop rate or the yearly step to compare.');
      set('caPaycheck', '');
    } else {
      set('caSummary', 'Raising your contribution by ' + pctFmt.format(step) + ' percentage point' + (step === 1 ? '' : 's') +
          ' a year from ' + pctFmt.format(start) + '% ' + (r.reached === null ? 'without reaching ' + pctFmt.format(stop) + '% before you retire'
          : 'until it reaches ' + pctFmt.format(stop) + '% at age ' + r.reached) + ' adds ' + money.format(r.bA - r.bF) +
          ' by age ' + retireAge + '.');
      if (r.rows.length > 1) {
        var extra = (r.rows[1].youA - r.rows[1].youF) / 12;
        set('caPaycheck', 'Next year the first increase takes about ' + money.format(extra) +
            ' a month more from your pay before tax, less if your contribution is pre-tax because it lowers your income tax.');
      } else set('caPaycheck', '');
    }
    var capNote = document.getElementById('caCapped');
    capNote.hidden = !r.capped;
    if (r.capped) capNote.textContent = 'In some years the contributions reach the ' + LIMITS.year +
      ' IRS limits, so they are capped there. Untick the limits option under More options to see the uncapped figures.';

    var body = document.getElementById('caSchedule');
    body.textContent = '';
    r.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      [row.age, money.format(row.salary), pctFmt.format(row.rate * 100) + '%', money.format(row.youF), money.format(row.youA),
       money.format(row.bF), money.format(row.bA)].forEach(function (v) {
        var td = document.createElement('td'); td.textContent = v; tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('caForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
